import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class SourceTargetNegativeReserveDelta {
 static final String P=SourceTargetNegativeReserveMethods.P,N=SourceTargetNegativeReserveMethods.N,V=SourceTargetNegativeReserveMethods.V,OLD=SourceTargetNegativeReserveMethods.OLD,METHOD=SourceTargetNegativeReserveMethods.METHOD;static void need(boolean b,String s){if(!b)throw new AssertionError(s);}static void load(MethodNode m,MethodInsnNode call,int slot){var p=FreezeAcceptedMethods.prev(call);need(p instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==slot,"exact first-proof operand "+slot);m.instructions.remove(p);}static void body(ClassNode a,MethodNode old,ClassNode b,MethodNode now){need(Arrays.equals(SourceNpcFirstViewDelta.body(a,old,old.name),SourceNpcFirstViewDelta.body(b,now,old.name)),"whole original inverse "+a.name+"."+old.name);}
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[0]);var jar=new JarFile(a[1])){var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(old.entries())){names.add(e.getName());var now=jar.getJarEntry(e.getName());need(now!=null,"original entry retained");if(!Arrays.equals(old.getInputStream(e).readAllBytes(),jar.getInputStream(now).readAllBytes()))changed.add(e.getName());}need(changed.equals(Set.of(V+".class",OLD+".class")),"only original reserve and caller owners");var added=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName()))added.add(e.getName());need(added.equals(Set.of(N+".class")),"one fieldless adapter only");int methods=0,ports=0,siblings=0;for(var owner:SourceTargetNegativeReserveMethods.OWNERS){var before=FreezeSourceTargetDelta.read(old,owner);var after=FreezeSourceTargetDelta.read(jar,owner);need(before.fields.size()==after.fields.size()&&after.methods.size()==before.methods.size()+(owner.equals(V)?1:0),"original fields and one complete native reserve sibling");for(int i=0;i<before.fields.size();i++){var f=before.fields.get(i);var g=after.fields.get(i);need(f.name.equals(g.name)&&f.desc.equals(g.desc)&&f.access==g.access&&Objects.equals(f.signature,g.signature)&&Objects.equals(f.value,g.value),"original field bytes retained");}for(var m:before.methods){var now=after.methods.stream().filter(x->x.name.equals(m.name)&&x.desc.equals(m.desc)).findFirst().orElseThrow();for(var node:now.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(N)){need(owner.equals(OLD)&&m.name.equals("cast")&&call.name.equals("reserve"),"one selected original peer reserve caller");load(now,call,4);call.owner=V;call.desc="(L"+P+"ClientSession;)L"+V+"$Receipt;";ports++;}body(before,m,after,now);methods++;}
 if(owner.equals(V)){var original=before.methods.stream().filter(m->m.name.equals("reserve")).findFirst().orElseThrow();var m=after.methods.stream().filter(x->x.name.equals(METHOD)).findFirst().orElseThrow();need(m.access==original.access,"original reserve access");int initial=0,life=0,processes=0,fence=0;for(var node:m.instructions.toArray())if(m.instructions.contains(node)&&node instanceof MethodInsnNode call&&call.owner.equals(N)){switch(call.name){case "initial"->{for(int slot:new int[]{2,1,0})load(m,call,slot);var branch=FreezeSourceTargetDelta.next(call);var nil=FreezeSourceTargetDelta.next(branch);var ret=FreezeSourceTargetDelta.next(nil);need(branch.getOpcode()==IFNE&&nil.getOpcode()==ACONST_NULL&&ret.getOpcode()==ARETURN,"bounded reserve prefix");for(var n:List.of(call,branch,nil,ret))m.instructions.remove(n);initial++;}case "lifetime"->{for(int slot:new int[]{2,1})load(m,call,slot);call.owner=P+"NativePlayerLifetime";call.name="of";call.desc="(L"+P+"ClientSession;)L"+P+"NativePlayerLifetime;";life++;}case "processes"->{for(int slot:new int[]{4,2,1,0})load(m,call,slot);m.instructions.remove(call);processes++;}case "current"->{for(int slot:new int[]{4,2,1,0})load(m,call,slot);var branch=FreezeSourceTargetDelta.next(call);need(branch instanceof JumpInsnNode j&&j.getOpcode()==IFEQ,"original null/unlock rejection branch");m.instructions.remove(branch);m.instructions.remove(call);fence++;}default->throw new AssertionError("unknown first reserve call "+call.name);}}need(initial==1&&life==1&&processes==1&&fence==1,"exact first-proof gates only");for(var node:m.instructions){if(node instanceof VarInsnNode x&&x.var>=3)x.var-=2;if(node instanceof IincInsnNode x&&x.var>=3)x.var-=2;}m.desc=original.desc;m.maxLocals=original.maxLocals;body(before,original,after,m);siblings++;}}
 need(ports==1&&siblings==1,"one original call plus one whole reserve sibling");System.out.println("PASS independent target-negative reserve inverse: "+methods+" original methods,1 original caller port,1 complete reserve sibling; original pending/app/Receipt/frame/rollback/locks/cost/RNG/SQL bodies retained");}}
}
